class BankAccount {
    protected double balance;
    public BankAccount(double balance) { this.balance = balance; }

    public boolean withdraw(double amount) {
        if (amount > 0 && balance >= amount) {
            balance -= amount;
            System.out.println("Success: Withdrew $" + amount + " | Balance: $" + balance);
            return true;
        }
        System.out.println("Failed: Insufficient funds");
        return false;
    }
}

class FeeCheckingAccount extends BankAccount {
    private double transactionFee;

    public FeeCheckingAccount(double balance, double fee) {
        super(balance);
        this.transactionFee = fee;
    }

    @Override
    public boolean withdraw(double amount) {
        // Step 1: Pre-process with fee calculation
        double totalDeduction = amount + transactionFee;
        System.out.println("[FeeChecking] Applying $" + transactionFee + " service fee.");

        // Step 2: Augment parent method with augmented amount
        return super.withdraw(totalDeduction);
    }
}

public class BankDemo {
    public static void main(String[] args) {
        BankAccount acc = new FeeCheckingAccount(100.0, 2.50);
        acc.withdraw(40.0);
    }
}

