class BasicLogger {
    public void log(String message) {
        System.out.println("[BASE LOG] " + message);
    }
}

class TimestampLogger extends BasicLogger {
    @Override
    public void log(String message) {
        String timestamped = "[2026-10-03 10:00:00] " + message;
        // Augment: call parent with timestamped payload
        super.log(timestamped);
    }
}

class SecurityAuditLogger extends TimestampLogger {
    @Override
    public void log(String message) {
        String secured = "[ENCRYPTED-ID: 994] " + message;
        // Augment: call parent (TimestampLogger)
        super.log(secured);
        System.out.println("-> Audit checkpoint confirmed.");
    }
}

public class LoggerDemo {
    public static void main(String[] args) {
        BasicLogger logger = new SecurityAuditLogger();
        logger.log("User login succeeded");
    }
}

