class Order {
    protected double subtotal;
    public Order(double subtotal) { this.subtotal = subtotal; }
    public double calculateTotal() {
        return subtotal;
    }
}

class TaxableOrder extends Order {
    private double taxRate;
    public TaxableOrder(double subtotal, double taxRate) {
        super(subtotal);
        this.taxRate = taxRate;
    }
    @Override
    public double calculateTotal() {
        double base = super.calculateTotal();
        return base + (base * taxRate);
    }
}

public class OrderApp {
    public static void main(String[] args) {
        Order order = new TaxableOrder(100.0, 0.08);
        System.out.println("Total: $" + order.calculateTotal());
    }
}

