class SimpleStack {
    protected int[] elements = new int[10];
    protected int top = 0;
    public void push(int val) {
        elements[top++] = val;
        System.out.println("Pushed: " + val);
    }
}

class BoundedStack extends SimpleStack {
    private int capacity;
    public BoundedStack(int capacity) {
        this.capacity = capacity;
    }
    @Override
    public void push(int val) {
        if (top >= capacity) {
            System.out.println("Error: Stack full (capacity: " + capacity + ")");
        } else {
            super.push(val);
        }
    }
}

public class StackApp {
    public static void main(String[] args) {
        SimpleStack stack = new BoundedStack(2);
        stack.push(10);
        stack.push(20);
        stack.push(30);
    }
}

