class Transaction {
    public boolean execute() {
        System.out.println("[1] Database transaction committed");
        return true;
    }
}

class TwoPhaseTransaction extends Transaction {
    @Override
    public boolean execute() {
        System.out.println("[2] Preparing 2-phase commit consensus");
        boolean ok = super.execute();
        System.out.println("[2] 2-phase consensus acknowledged");
        return ok;
    }
}

class DistributedTransaction extends TwoPhaseTransaction {
    @Override
    public boolean execute() {
        System.out.println("[3] Synchronizing across geographic regions");
        boolean ok = super.execute();
        System.out.println("[3] Global lock released");
        return ok;
    }
}

public class TransactionPipelineApp {
    public static void main(String[] args) {
        Transaction txn = new DistributedTransaction();
        txn.execute();
    }
}
